   102→FIntPoint UWjWorldBrickSpawner::CalculateBrickGridIndex(const FVector& WorldLocation, int32 ColNum, int32 RowNum, const FVector& WallOrigin, const FVector& BrickSize)
   103→{
   104→	// 그리드 중심 인덱스 (정중앙 기준)
   105→	const float CenterCol = (ColNum - 1) * 0.5f;
   106→	const float CenterRow = (RowNum - 1) * 0.5f;
   107→
   108→	// 월드 오프셋 계산
   109→	const float WorldOffsetX = WorldLocation.X - WallOrigin.X;
   110→	const float WorldOffsetY = WorldLocation.Y - WallOrigin.Y;
   111→
   112→	// 그리드 오프셋 계산
   113→	const float ColOffset = WorldOffsetX / BrickSize.X;
   114→	const float RowOffset = WorldOffsetY / BrickSize.Y;
   115→
   116→	// 그리드 인덱스 계산 (반올림하여 가장 가까운 셀로)
   117→	const int32 ColIndex = FMath::RoundToInt32(ColOffset + CenterCol);
   118→	const int32 RowIndex = FMath::RoundToInt32(RowOffset + CenterRow);
   119→
   120→	return FIntPoint(ColIndex, RowIndex);
   121→}
