   128→void UWjWorldBrickSpawner::Tick(float DeltaTime)
   129→{
   130→	UWorld* World = GetWorld();
   131→	if (World == nullptr) return;
   132→
   133→	bool bIsLayoutValid = TargetDesc.IsLayoutValid();
   134→	if (bIsLayoutValid == false)
   135→	{
   136→		UE_LOG(LogWjWorld, Error, TEXT("Wall Description Layout is Invalid"));
   137→		CurrentLoadingBrickColIndex = 0;
   138→		CurrentLoadingBrickRowIndex = 0;
   139→		SetTickable(false);
   140→		return;
   141→	}
   142→
   143→	int32 ProcessedCellsCount = 0;
   144→	bool bFinishedSpawning = false;
   145→
   146→	while (ProcessedCellsCount < CheckCellCountPerTick
   147→		&& bFinishedSpawning == false)
   148→	{
   149→		int32 BrickType = TargetDesc.WallLayout[CurrentLoadingBrickRowIndex][CurrentLoadingBrickColIndex];
   150→		++ProcessedCellsCount;
   151→
   152→		if (BrickType >= (int32)EWjWorldBrickType::Standard)
   153→		{
   154→			FWjWorldBrickProperties BrickProperties;
   155→			BrickProperties.BrickType = static_cast<EWjWorldBrickType>(BrickType);
   156→			BrickProperties.BrickMoveType = EWjWorldBrickMoveType::Standard;
   157→			BrickProperties.Size = TargetDesc.BrickSize;
   158→			BrickProperties.Color = FColor::White;
   159→			BrickProperties.SpawnedGridPosition = FIntPoint(CurrentLoadingBrickColIndex, CurrentLoadingBrickRowIndex);
   160→			BrickProperties.CenterOffset = TargetDesc.CenterOffset;
   161→			BrickProperties.ColumnNum = TargetDesc.ColumnNum;
   162→			BrickProperties.RowNum = TargetDesc.RowNum;
   163→
   164→			// Destructible 벽돌은 DeveloperSettings에서 MaxHP 설정
   165→			if (BrickProperties.BrickType == EWjWorldBrickType::Destructible)
   166→			{
   167→				BrickProperties.MaxHP = GetDefault<UWjWorldDeveloperSettings>()->DestructibleBrickDefaultHP;
   168→			}
   169→
   170→			SpawnBrickActor(World, BrickProperties, CurrentLoadingBrickColIndex, CurrentLoadingBrickRowIndex);
   171→		}
   172→		else if (BrickType < (int32)EWjWorldBrickType::Standard
   173→			&& TargetDesc.SafeZonesSet.Contains(FIntPoint(CurrentLoadingBrickColIndex, CurrentLoadingBrickRowIndex)))
   174→		{
   175→			FVector TilePosition = CalculateBrickPosition(
   176→				CurrentLoadingBrickColIndex,
   177→				CurrentLoadingBrickRowIndex,
   178→				TargetDesc.ColumnNum,
   179→				TargetDesc.RowNum,
   180→				TargetDesc.CenterOffset,
   181→				TargetDesc.BrickSize);
   182→
   183→			// 바둑판 패턴: (Column + Row) % 2로 검정/흰색 결정
   184→			const bool bIsWhiteTile = (CurrentLoadingBrickColIndex + CurrentLoadingBrickRowIndex) % 2 == 0;
   185→
   186→			// Deferred Spawn: InitializeTile 후 BeginPlay 호출
   187→			AWjWorldTileActor* TileActor = World->SpawnActorDeferred<AWjWorldTileActor>(
   188→				TileActorClass ? TileActorClass.Get() : AWjWorldTileActor::StaticClass(),
   189→				FTransform(TilePosition));
   190→
   191→			if (TileActor)
   192→			{
   193→				TileActor->InitializeTile(TargetDesc.BrickSize, TilePosition, bIsWhiteTile);
   194→				TileActor->FinishSpawning(FTransform(TilePosition));
   195→			}
   196→		}
   197→
   198→		CurrentLoadingBrickColIndex++;
   199→		if (TargetDesc.WallLayout[CurrentLoadingBrickRowIndex].IsValidIndex(CurrentLoadingBrickColIndex) == false)
   200→		{
   201→			CurrentLoadingBrickColIndex = 0;
   202→			CurrentLoadingBrickRowIndex++;
   203→
   204→			if (TargetDesc.WallLayout.IsValidIndex(CurrentLoadingBrickRowIndex) == false)
   205→			{
   206→				CurrentLoadingBrickColIndex = 0;
   207→				CurrentLoadingBrickRowIndex = 0;
   208→				bFinishedSpawning = true;
   209→				SetTickable(false);
   210→				UE_LOG(LogWjWorld, Log, TEXT("Finished Spawning All Bricks"));
   211→			}
   212→		}
   213→	}
   214→
   215→	if (bFinishedSpawning)
   216→	{
   217→		TArray<FIntPoint> RandomSafeZonePoints;
   218→		TargetDesc.GetRandomSafeZones(RandomSafeZonePoints);
   219→
   220→		StartSafeZonePoints = TargetDesc.SafeZones;
   221→
   222→		TArray<FVector> RandomSafeZoneLocations;
   223→		for(const FIntPoint& SafeZonePoint : RandomSafeZonePoints)
   224→		{
   225→			FVector SafeZoneLocation = CalculateBrickPosition(
   226→				SafeZonePoint.X,
   227→				SafeZonePoint.Y,
   228→				TargetDesc.ColumnNum,
   229→				TargetDesc.RowNum,
   230→				TargetDesc.CenterOffset,
   231→				TargetDesc.BrickSize);
   232→			RandomSafeZoneLocations.Add(SafeZoneLocation);
   233→		}
   234→
   235→		OnWallSpawnFinished.Broadcast(RandomSafeZoneLocations, TargetDesc);
   236→		TargetDesc.Reset();
   237→	}
   238→
   239→	UE_LOG(LogWjWorld, Warning,
   240→		TEXT("Tick Start: Row=%d Col=%d bTickable=%d"),
   241→		CurrentLoadingBrickRowIndex,
   242→		CurrentLoadingBrickColIndex,
   243→		bTickable);
   244→}
