    21→void AWjWorldBrickPreviewActor::BeginPlay()
    22→{
    23→	Super::BeginPlay();
    24→
    25→	if (PreviewMeshComponent)
    26→	{
    27→		// DeveloperSettings에서 메시 로드
    28→		UStaticMesh* BrickMesh = UWjWorldBrickComponent::GetBrickMesh();
    29→		if (BrickMesh)
    30→		{
    31→			PreviewMeshComponent->SetStaticMesh(BrickMesh);
