    60→void AWjWorldTileActor::InitializeTile(const FVector& InSize, const FVector& InCenterOffset, bool bInIsWhiteTile)
    61→{
    62→	if (!HasAuthority()) return;
    63→
    64→	FVector TileLocation = InCenterOffset;
    65→	TileLocation.Z -= InSize.Z * 0.5f; // 타일이 바닥에 위치하도록 Z 오프셋 조정
    66→	SetActorLocation(TileLocation);
    67→	UE_LOG(LogWjWorld, Log, TEXT("Tile Initialized at Location: %s"), *InCenterOffset.ToString());
    68→
    69→	// FinishSpawning 전에 설정하여 Initial Bunch에 포함
    70→	bIsWhiteTile = bInIsWhiteTile;
    71→
    72→	float Offset = HitBoxSize + 2.0f;
    73→
    74→	// ⭐ InSize는 타일 전체 크기, HalfExtent는 절반
    75→	const FVector HalfExtent = InSize * 0.5f;
    76→
    77→	for (int32 DirectionIndex = 0; DirectionIndex < EWjWorldDirection::Max; ++DirectionIndex)
    78→	{
    79→		if (HitBoxComponents[DirectionIndex] == nullptr) continue;
    80→
    81→		FVector BoxLocation = FVector::ZeroVector;
    82→
    83→		// 방향별 HitBox는 타일 경계 끝에 배치 (half extent 기준)
    84→		switch (DirectionIndex)
    85→		{
    86→		case EWjWorldDirection::Up:
    87→		{
    88→			BoxLocation = FVector(0.0f, HalfExtent.Y + Offset, 0.0f);
    89→			break;
    90→		}
    91→
    92→		case EWjWorldDirection::Right:
    93→		{
    94→			BoxLocation = FVector(HalfExtent.X + Offset, 0.0f, 0.0f);
    95→			break;
    96→		}
    97→
    98→		case EWjWorldDirection::Down:
    99→		{
   100→			BoxLocation = FVector(0.0f, -HalfExtent.Y - Offset, 0.0f);
   101→			break;
   102→		}
   103→
   104→		case EWjWorldDirection::Left:
   105→		{
   106→			BoxLocation = FVector(-HalfExtent.X - Offset, 0, 0.0f);
   107→			break;
   108→		}
   109→		}
   110→
   111→		HitBoxComponents[DirectionIndex]->SetRelativeLocation(BoxLocation);
   112→		HitBoxComponents[DirectionIndex]->OnComponentBeginOverlap.AddDynamic(this, &AWjWorldTileActor::OnBrickOverlapBegin);
   113→		HitBoxComponents[DirectionIndex]->OnComponentEndOverlap.AddDynamic(this, &AWjWorldTileActor::OnBrickOverlapEnd);
   114→	}
   115→
   116→	// ⭐ SetBoxExtent는 half extent를 받으므로 InSize * 0.5f 전달
   117→	CenterHitBoxComponent->SetBoxExtent(HalfExtent);
   118→	CenterHitBoxComponent->OnComponentBeginOverlap.AddDynamic(this, &AWjWorldTileActor::OnBrickOverlapBegin);
   119→	CenterHitBoxComponent->OnComponentEndOverlap.AddDynamic(this, &AWjWorldTileActor::OnBrickOverlapEnd);
   120→
   121→	if (TileMeshComponent)
   122→	{
   123→		TileMeshComponent->SetWorldScale3D(InSize / 100.0f); // 기본 메시 크기가 100이므로 스케일 조정
   124→	}
   125→}
