   181→// Called every frame
   182→void AWjWorldTileActor::Tick(float DeltaTime)
   183→{
   184→	Super::Tick(DeltaTime);
   185→
   186→	if (bIsBombSignalOn == false) return;
   187→
   188→	ElapsedBombingTime += DeltaTime;
   189→
   190→	// Warning -> Danger 색상 보간
   191→	if (DynamicMaterial)
   192→	{
   193→		const float Alpha = FMath::Clamp(ElapsedBombingTime / BombChargingTime, 0.0f, 1.0f);
   194→		const FLinearColor WarningColor = FLinearColor(BombSignalOnColorWarning);
   195→		const FLinearColor DangerColor = FLinearColor(BombSignalOnColorDanger);
   196→		const FLinearColor LerpedColor = FMath::Lerp(WarningColor, DangerColor, Alpha);
   197→		DynamicMaterial->SetVectorParameterValue(TEXT("BaseColor"), FVector(LerpedColor.R, LerpedColor.G, LerpedColor.B));
   198→	}
   199→
   200→	if (ElapsedBombingTime >= BombChargingTime)
   201→	{
   202→		if (HasAuthority())
   203→		{
   204→			Bomb();
   205→			bIsBombSignalOn = false;
   206→			OnRep_IsBombSignalOn();
   207→		}
   208→
   209→		ElapsedBombingTime = 0.0f;
   210→	}
   211→}
