   220→void AWjWorldTileActor::OnBrickOverlapBegin(UPrimitiveComponent* OverlappedComponent, AActor* OtherActor,
   221→	UPrimitiveComponent* OtherComp, int32 OtherBodyIndex, bool bFromSweep, const FHitResult& SweepResult)
   222→{
   223→	// 서버에서만 처리
   224→	if (GetLocalRole() != ROLE_Authority) return;
   225→	
   226→	AWjWorldBrickActor* BrickActor = Cast<AWjWorldBrickActor>(OtherActor);
   227→	if (!BrickActor) return;
   228→
   229→	for (int32 DirectionIndex = 0; DirectionIndex < EWjWorldDirection::Max; ++DirectionIndex)
   230→	{
   231→		if (HitBoxComponents[DirectionIndex] == OverlappedComponent)
   232→		{
   233→			++bIsOverlapBricks[DirectionIndex];
   234→		}
   235→	}
   236→
   237→	if (WjWorldGameplayUtils::IsGameplayPhaseplaying(GetWorld()))
   238→	{
   239→		if (bIsBombSignalOn == false && CheckBombSignalOn())
   240→		{
   241→			bIsBombSignalOn = true;
   242→			OnRep_IsBombSignalOn();
   243→		}
   244→	}
   245→}
   246→
   247→void AWjWorldTileActor::OnBrickOverlapEnd(UPrimitiveComponent* OverlappedComponent, AActor* OtherActor, UPrimitiveComponent* OtherComp, int32 OtherBodyIndex)
   248→{
   249→	if (GetLocalRole() != ROLE_Authority) return;
   250→
   251→	AWjWorldBrickActor* BrickActor = Cast<AWjWorldBrickActor>(OtherActor);
   252→	if (!BrickActor) return;
   253→
   254→	if (OverlappedComponent == CenterHitBoxComponent)
   255→	{
   256→		const FWjWorldBrickProperties& BrickProperties = BrickActor->GetBrickComponent()->GetBrickProperties();
   257→		if (BrickProperties.BrickType == EWjWorldBrickType::Standard)
   258→		{
   259→			Destroy();
   260→			return;
   261→		}
   262→	}
   263→	else
   264→	{
   265→		for (int32 DirectionIndex = 0; DirectionIndex < EWjWorldDirection::Max; ++DirectionIndex)
   266→		{
   267→			if (HitBoxComponents[DirectionIndex] == OverlappedComponent)
   268→			{
   269→				--bIsOverlapBricks[DirectionIndex];
   270→				bIsOverlapBricks[DirectionIndex] = FMath::Max(0, bIsOverlapBricks[DirectionIndex]);
   271→			}
   272→		}
   273→	}
   274→
   275→	if (WjWorldGameplayUtils::IsGameplayPhaseplaying(GetWorld()))
   276→	{
   277→		if (bIsBombSignalOn && !CheckBombSignalOn())
   278→		{
   279→			bIsBombSignalOn = false;
   280→			OnRep_IsBombSignalOn();
   281→		}
   282→	}
   283→}
   284→
   285→bool AWjWorldTileActor::CheckBombSignalOn() const
   286→{
   287→	for (int32 DirectionIndex = 0; DirectionIndex < EWjWorldDirection::Max; ++DirectionIndex)
   288→	{
   289→		if (bIsOverlapBricks[DirectionIndex] <= 0)
   290→		{
   291→			return false;
   292→		}
   293→	}
   294→
   295→	return true;
   296→}
