   298→void AWjWorldTileActor::Bomb()
   299→{
   300→	if (GetLocalRole() != ROLE_Authority) return;
   301→	if (WjWorldGameplayUtils::IsGameplayPhaseplaying(GetWorld()) == false) return;
   302→
   303→	TArray<AActor*> BombedActors;
   304→	CenterHitBoxComponent->GetOverlappingActors(BombedActors, AWjWorldCharacterPlay::StaticClass());
   305→
   306→	// 타일의 실제 경계 계산 (옆 칸에 있는 캐릭터 제외)
   307→	const FVector TileCenter = GetActorLocation();
   308→	const FVector TileExtent = CenterHitBoxComponent->GetScaledBoxExtent();
   309→	// 경계를 약간 줄여서 타일 경계에 선 캐릭터가 양쪽에서 처리되지 않도록 함
   310→	const float BoundaryMargin = 5.0f; // 5cm 마진
   311→	const FBox TileBounds(TileCenter - TileExtent + FVector(BoundaryMargin), TileCenter + TileExtent - FVector(BoundaryMargin));
   312→
   313→	for (AActor* BombedActor : BombedActors)
   314→	{
   315→		AWjWorldCharacterPlay* Character = Cast<AWjWorldCharacterPlay>(BombedActor);
   316→		if (Character == nullptr) continue;
   317→
   318→		// 캐릭터의 중심점이 이 타일 경계 내에 있는지 확인
   319→		const FVector CharacterLocation = Character->GetActorLocation();
   320→		if (!TileBounds.IsInsideXY(CharacterLocation))
   321→		{
   322→			UE_LOG(LogWjWorld, Verbose, TEXT("AWjWorldTileActor::Bomb - Character at %s is outside tile bounds, skipping"),
   323→				*CharacterLocation.ToString());
   324→			continue;
   325→		}
   326→
   327→		if (GameRule.IsValid())
   328→		{
   329→			GameRule->OnPlayerEliminated(Character);
   330→		}
   331→	}
   332→
   333→	SpawnBombEffect();
   334→}
