   336→void AWjWorldTileActor::OnRep_IsBombSignalOn()
   337→{
   338→	ElapsedBombingTime = 0.0f;
   339→
   340→	// 폭탄 신호가 꺼지면 기본 색상으로 복원
   341→	if (!bIsBombSignalOn && DynamicMaterial)
   342→	{
   343→		DynamicMaterial->SetVectorParameterValue(TEXT("BaseColor"), DefaultBaseColor);
   344→	}
   345→
   346→	UE_LOG(LogWjWorld, Log, TEXT("AWjWorldTileActor::OnRep_IsBombSignalOn: %d"), bIsBombSignalOn);
   347→}
