   354→		GetActorLocation(),
   355→		GetActorRotation(),
   356→		GetActorScale3D(),  // Scale
   357→		true,           // Auto Destroy
   358→		true,           // Auto Activate
   359→		ENCPoolMethod::None
   360→	);
   361→
   362→	UE_LOG(LogWjWorld, Log, TEXT("AWjWorldTileActor::SpawnBombEffect_Implementation"));
   363→}
