     8→
     9→#include "Core/Play/WjWorldGameModePlay.h"
    10→#include "Core/Play/WjWorldCharacterPlay.h"
    11→#include "Core/GameRule/WjWorldGameRuleApproachingWall.h"
    12→#include "Setting/WjWorldDeveloperSettings.h"
    13→#include "Components/BoxComponent.h"
    14→
    15→#include "Engine/OverlapResult.h"
    16→
    17→#include "Net/UnrealNetwork.h"
    18→
    19→UStaticMesh* UWjWorldBrickComponent::GetBrickMesh()
    20→{
    21→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
    22→	if (Settings && !Settings->BrickMesh.IsNull())
    23→	{
    24→		return Settings->BrickMesh.LoadSynchronous();
    25→	}
    26→	return nullptr;
    27→}
    28→
    29→UWjWorldBrickComponent::UWjWorldBrickComponent()
    30→{
    31→	PrimaryComponentTick.bCanEverTick = true;
    32→
    33→	
    34→}
    35→
    36→void UWjWorldBrickComponent::InitializeBrick(const FWjWorldBrickProperties& InBrickProperties)
    37→{
    38→	if (GetOwnerRole() == ROLE_Authority)
    39→	{
    40→		this->BrickProperties = InBrickProperties;
    41→		this->CurrentHP = InBrickProperties.MaxHP;
    42→
    43→		switch (InBrickProperties.BrickMoveType)
    44→		{
    45→		case EWjWorldBrickMoveType::Standard:
    46→		{
    47→			BrickMovement = NewObject<UWjWorldBrickMovement>(this, UWjWorldBrickMovement::StaticClass());
    48→			BrickMovement->Initialize(this, Cast<UWjWorldGameRuleApproachingWall>(GetGameModePlay()->GetCurrentGameRule()));
    49→			break;
    50→		}
    51→		}
    52→	}
    53→}
    54→
    55→void UWjWorldBrickComponent::ReserveDestroyBrick(float AfterSeconds)
    56→{
    57→	if (GetOwnerRole() == ROLE_Authority)
    58→	{
    59→		GetWorld()->GetTimerManager().SetTimer(DestroyHandle, [this]() {
    60→			if (AActor* OwnerActor = GetOwner())
    61→			{
    62→				OwnerActor->Destroy();
    63→			}
    64→			}, AfterSeconds, false);
    65→	}
    66→}
    67→
    68→// Called when the game starts
    69→void UWjWorldBrickComponent::BeginPlay()
    70→{
    71→	Super::BeginPlay();
    72→
    73→	if (GetOwnerRole() == ROLE_Authority)
    74→	{
    75→		GetGameModePlay()->OnGameLevelChange.AddUObject(this, &UWjWorldBrickComponent::OnBrickMovementSignal);
    76→	}
    77→
    78→	if (BrickMeshComponent)
    79→	{
    80→		// Set mesh, size, and color based on BrickProperties
    81→		FVector Scale = BrickProperties.Size / 100.0f; // Assuming the default mesh size is 100 units
    82→		BrickMeshComponent->SetWorldScale3D(Scale);
    83→
    84→		// 대각선 이동을 위해 물리 차단은 별도 BoxComponent(95%)로 처리
    85→		// BrickMeshComponent는 TileActor overlap 감지용으로 QueryOnly + Overlap 유지
    86→		BrickMeshComponent->SetCollisionEnabled(ECollisionEnabled::QueryOnly);
    87→		BrickMeshComponent->SetCollisionResponseToAllChannels(ECR_Overlap);
    88→		BrickMeshComponent->SetGenerateOverlapEvents(true);
    89→
    90→		UStaticMesh* BrickMesh = GetBrickMesh();
    91→		if (BrickMesh)
    92→		{
    93→			BrickMeshComponent->SetStaticMesh(BrickMesh);
    94→		}
    95→
    96→		UMaterialInstanceDynamic* DynamicMaterial = BrickMeshComponent->CreateAndSetMaterialInstanceDynamic(0);
    97→		if (DynamicMaterial)
    98→		{
    99→			DynamicMaterial->SetVectorParameterValue(FName("BaseColor"), FLinearColor(BrickProperties.GetColorWithBrickType()));
   100→			DynamicMaterial->SetScalarParameterValue(FName("CrackIntensity"), 0.0f);
   101→		}
   102→	}
   103→
   104→	// BlockingCollisionComponent 크기 설정 (실제 크기의 95%로 대각선 통과 가능하게)
   105→	if (BlockingCollisionComponent)
   106→	{
   107→		// BoxExtent는 half-size이므로 Size의 절반을 사용
   108→		const FVector CollisionHalfSize = BrickProperties.Size * 0.475f; // 95% / 2 = 0.475
   109→		BlockingCollisionComponent->SetBoxExtent(CollisionHalfSize);
   110→	}
   111→}
   112→
   113→void UWjWorldBrickComponent::EndPlay(EEndPlayReason::Type Reason)
   114→{
   115→	Super::EndPlay(Reason);
   116→
   117→	if (GetOwnerRole() == ROLE_Authority)
   118→	{
   119→		GetGameModePlay()->OnGameLevelChange.RemoveAll(this);
   120→		GetWorld()->GetTimerManager().ClearTimer(DestroyHandle);
   121→	}
   122→}
   123→
   124→void UWjWorldBrickComponent::OnRegister()
   125→{
   126→	Super::OnRegister();
   127→
   128→	CenterHitBoxComponent = NewObject<UBoxComponent>(this, UBoxComponent::StaticClass(), TEXT("CenterHitBoxComponent"));
   129→	CenterHitBoxComponent->AttachToComponent(this, FAttachmentTransformRules::KeepRelativeTransform);
   130→	CenterHitBoxComponent->SetCollisionProfileName(TEXT("OverlapAllDynamic"));
   131→	CenterHitBoxComponent->SetBoxExtent(FVector(HitBoxSize, HitBoxSize, HitBoxSize));
   132→
   133→	// 캐릭터 blocking collision용 BoxComponent (대각선 이동을 위해 크기 축소)
   134→	BlockingCollisionComponent = NewObject<UBoxComponent>(this, UBoxComponent::StaticClass(), TEXT("BlockingCollisionComponent"));
   135→	BlockingCollisionComponent->AttachToComponent(this, FAttachmentTransformRules::KeepRelativeTransform);
   136→	BlockingCollisionComponent->SetCollisionProfileName(TEXT("BlockAll"));
   137→	BlockingCollisionComponent->SetGenerateOverlapEvents(false); // TileActor overlap 감지에 간섭 방지
   138→	BlockingCollisionComponent->SetBoxExtent(FVector(HitBoxSize, HitBoxSize, HitBoxSize)); // BeginPlay에서 실제 크기 설정
   139→
   140→	BrickMeshComponent = NewObject<UStaticMeshComponent>(this, UStaticMeshComponent::StaticClass(), TEXT("BrickMeshComponent"));
   141→	BrickMeshComponent->AttachToComponent(this, FAttachmentTransformRules::KeepRelativeTransform);
   142→	BrickMeshComponent->RegisterComponent();
   143→	//BrickMeshComponent->SetIsReplicated(true);
   144→}
   145→
   146→void UWjWorldBrickComponent::GetLifetimeReplicatedProps(TArray<FLifetimeProperty>& OutLifetimeProps) const
   147→{
   148→	Super::GetLifetimeReplicatedProps(OutLifetimeProps);
   149→	DOREPLIFETIME_CONDITION(UWjWorldBrickComponent, BrickProperties, COND_InitialOnly);
   150→	DOREPLIFETIME(UWjWorldBrickComponent, CurrentHP);
   151→}
   152→
   153→// Called every frame
   154→void UWjWorldBrickComponent::TickComponent(float DeltaTime, ELevelTick TickType, FActorComponentTickFunction* ThisTickFunction)
   155→{
   156→	Super::TickComponent(DeltaTime, TickType, ThisTickFunction);
   157→
   158→	if (GetOwnerRole() == ROLE_Authority)
   159→	{
   160→		if (BrickMovement)
   161→		{
   162→			BrickMovement->Tick(DeltaTime);
   163→		}
   164→	}
   165→}
   166→
   167→void UWjWorldBrickComponent::OnBrickMovementSignal(int32 BrickMoveSignalCount)
   168→{
   169→	if (BrickMovement)
   170→	{
   171→		CurrentBrickMoveSignalCount = BrickMoveSignalCount;
   172→
   173→		if (BrickProperties.BrickType == EWjWorldBrickType::Standard)
   174→		{
   175→			BrickMovement->MoveBrick(UWjWorldWallManager::GetBrickMovementAllowedTime(BrickMoveSignalCount));
   176→		}
   177→	}
   178→}
   179→
   180→void UWjWorldBrickComponent::HandleWallCollision(const FVector& WallDirection)
   181→{
   182→	if (GetOwnerRole() != ROLE_Authority) return;
   183→
   184→	OnWallCollision.Broadcast(this, WallDirection);
   185→
   186→	switch (BrickProperties.BrickType)
   187→	{
   188→	case EWjWorldBrickType::Explosive:
   189→		Explode();
   190→		DestroyBrick();
   191→		break;
   192→
   193→	case EWjWorldBrickType::Destructible:
   194→		// 벽 충돌은 HP 무시하고 즉시 파괴 + 파쇄 연출
   195→		if (AWjWorldBrickActor* BrickActor = Cast<AWjWorldBrickActor>(GetOwner()))
   196→		{
   197→			BrickActor->MulticastSpawnDestructionFracture();
   198→		}
   199→		DestroyBrick();
   200→		break;
   201→
   202→	case EWjWorldBrickType::Moving:
   203→		PushInDirection(WallDirection, UWjWorldWallManager::GetBrickMovementAllowedTime(CurrentBrickMoveSignalCount));
   204→		break;
   205→
   206→	case EWjWorldBrickType::Standard:
   207→		// Standard는 벽 자체이므로 충돌 처리 없음
   208→		break;
   209→	}
   210→}
   211→
   212→void UWjWorldBrickComponent::PushInDirection(const FVector& Direction, float MoveTime)
   213→{
   214→	if (!BrickMovement) return;
   215→
   216→	BrickMovement->PushBrick(Direction, MoveTime);
   217→}
   218→
   219→void UWjWorldBrickComponent::Explode()
   220→{
   221→	if (GetOwnerRole() != ROLE_Authority) return;
   222→
   223→	// 폭발 VFX
   224→	if (AWjWorldBrickActor* BrickActor = Cast<AWjWorldBrickActor>(GetOwner()))
   225→	{
   226→		BrickActor->MulticastSpawnExplosionEffect();
   227→	}
   228→
   229→	// 상하좌우 데미지 처리
   230→	const FVector& BrickSize = BrickProperties.Size;
   231→	const FVector CurrentLocation = GetComponentLocation();
   232→
   233→	TArray<FVector> ExplosionDirections = {
   234→		FVector(BrickSize.X, 0.0f, 0.0f),   // Right
   235→		FVector(-BrickSize.X, 0.0f, 0.0f),  // Left
   236→		FVector(0.0f, BrickSize.Y, 0.0f),   // Up
   237→		FVector(0.0f, -BrickSize.Y, 0.0f)   // Down
   238→	};
   239→
   240→	for (const FVector& Dir : ExplosionDirections)
   241→	{
   242→		FVector CheckLocation = CurrentLocation + Dir;
   243→
   244→		// 해당 위치의 캐릭터나 다른 오브젝트에 데미지
   245→		TArray<FOverlapResult> Overlaps;
   246→		FCollisionShape CollisionShape = FCollisionShape::MakeBox(BrickSize * 0.4f);
   247→
   248→		if (GetWorld()->OverlapMultiByChannel(
   249→			Overlaps,
   250→			CheckLocation,
   251→			FQuat::Identity,
   252→			ECC_Pawn,
   253→			CollisionShape))
   254→		{
   255→			for (const FOverlapResult& Overlap : Overlaps)
   256→			{
   257→				if (AWjWorldCharacterPlay* Character = Cast<AWjWorldCharacterPlay>(Overlap.GetActor()))
   258→				{
   259→					// 캐릭터에 데미지 또는 제거 처리
   260→					if (UWjWorldGameRuleApproachingWall* GameRule = Cast<UWjWorldGameRuleApproachingWall>(GetGameModePlay()->GetCurrentGameRule()))
   261→					{
   262→						GameRule->OnPlayerEliminated(Character);
   263→					}
   264→				}
   265→			}
   266→		}
   267→	}
   268→}
   269→
   270→void UWjWorldBrickComponent::DestroyBrick()
   271→{
   272→	// 파괴 VFX
   273→	if (AWjWorldBrickActor* BrickActor = Cast<AWjWorldBrickActor>(GetOwner()))
   274→	{
   275→		BrickActor->MulticastSpawnDestroyEffect();
   276→	}
   277→
   278→	ReserveDestroyBrick(0.1f);
   279→}
   280→
   281→void UWjWorldBrickComponent::ApplyDamage(int32 DamageAmount)
   282→{
   283→	if (GetOwnerRole() != ROLE_Authority) return;
   284→	if (CurrentHP <= 0) return;
   285→
   286→	CurrentHP = FMath::Max(0, CurrentHP - DamageAmount);
   287→
   288→	if (CurrentHP <= 0)
   289→	{
   290→		// HP 소진 → 파쇄 연출 + 파괴
   291→		if (AWjWorldBrickActor* BrickActor = Cast<AWjWorldBrickActor>(GetOwner()))
   292→		{
   293→			BrickActor->MulticastSpawnDestructionFracture();
   294→		}
   295→		DestroyBrick();
   296→	}
