    89→// Called when the game starts
    90→void UWjWorldBrickComponent::BeginPlay()
    91→{
    92→	Super::BeginPlay();
    93→
    94→	if (GetOwnerRole() == ROLE_Authority)
    95→	{
    96→		GetGameModePlay()->OnGameLevelChange.AddUObject(this, &UWjWorldBrickComponent::OnBrickMovementSignal);
    97→	}
    98→
    99→	if (BrickMeshComponent)
   100→	{
   101→		// Set mesh, size, and color based on BrickProperties
   102→		FVector Scale = BrickProperties.Size / 100.0f; // Assuming the default mesh size is 100 units
   103→		BrickMeshComponent->SetWorldScale3D(Scale);
   104→
   105→		// 대각선 이동을 위해 물리 차단은 별도 BoxComponent(95%)로 처리
   106→		// BrickMeshComponent는 TileActor overlap 감지용으로 QueryOnly + Overlap 유지
   107→		BrickMeshComponent->SetCollisionEnabled(ECollisionEnabled::QueryOnly);
   108→		BrickMeshComponent->SetCollisionResponseToAllChannels(ECR_Overlap);
   109→		BrickMeshComponent->SetGenerateOverlapEvents(true);
   110→
   111→		UStaticMesh* BrickMesh = GetBrickMesh();
   112→		if (BrickMesh)
   113→		{
   114→			BrickMeshComponent->SetStaticMesh(BrickMesh);
   115→		}
   116→
   117→		// 타입별 머티리얼 적용 (DeveloperSettings에 설정된 경우)
   118→		UMaterialInterface* TypeMaterial = GetBrickMaterial(BrickProperties.BrickType);
   119→		if (TypeMaterial)
   120→		{
   121→			BrickMeshComponent->SetMaterial(0, TypeMaterial);
   122→		}
   123→
   124→		UMaterialInstanceDynamic* DynamicMaterial = BrickMeshComponent->CreateAndSetMaterialInstanceDynamic(0);
   125→		if (DynamicMaterial)
   126→		{
   127→			// 타입별 머티리얼이 없으면 기존 색상 폴백
   128→			if (!TypeMaterial)
   129→			{
   130→				DynamicMaterial->SetVectorParameterValue(FName("BaseColor"), FLinearColor(BrickProperties.GetColorWithBrickType()));
   131→			}
   132→			DynamicMaterial->SetScalarParameterValue(FName("CrackIntensity"), 0.0f);
   133→		}
   134→	}
   135→
   136→	// BlockingCollisionComponent 크기 설정 (실제 크기의 95%로 대각선 통과 가능하게)
   137→	if (BlockingCollisionComponent)
   138→	{
   139→		// BoxExtent는 half-size이므로 Size의 절반을 사용
   140→		const FVector CollisionHalfSize = BrickProperties.Size * 0.475f; // 95% / 2 = 0.475
   141→		BlockingCollisionComponent->SetBoxExtent(CollisionHalfSize);
   142→	}
   143→}
