   212→void UWjWorldBrickComponent::HandleWallCollision(const FVector& WallDirection)
   213→{
   214→	if (GetOwnerRole() != ROLE_Authority) return;
   215→
   216→	OnWallCollision.Broadcast(this, WallDirection);
   217→
   218→	switch (BrickProperties.BrickType)
   219→	{
   220→	case EWjWorldBrickType::Explosive:
   221→		Explode();
   222→		DestroyBrick();
   223→		break;
   224→
   225→	case EWjWorldBrickType::Destructible:
   226→		// 벽 충돌은 HP 무시하고 즉시 파괴 + 파쇄 연출
   227→		if (AWjWorldBrickActor* BrickActor = Cast<AWjWorldBrickActor>(GetOwner()))
   228→		{
   229→			BrickActor->MulticastSpawnDestructionFracture();
   230→		}
   231→		DestroyBrick();
   232→		break;
   233→
   234→	case EWjWorldBrickType::Moving:
   235→		PushInDirection(WallDirection, UWjWorldWallManager::GetBrickMovementAllowedTime(CurrentBrickMoveSignalCount));
   236→		break;
   237→
   238→	case EWjWorldBrickType::Standard:
   239→		// Standard는 벽 자체이므로 충돌 처리 없음
   240→		break;
   241→	}
   242→}
