   251→void UWjWorldBrickComponent::Explode()
   252→{
   253→	if (GetOwnerRole() != ROLE_Authority) return;
   254→
   255→	// 폭발 VFX
   256→	if (AWjWorldBrickActor* BrickActor = Cast<AWjWorldBrickActor>(GetOwner()))
   257→	{
   258→		BrickActor->MulticastSpawnExplosionEffect();
   259→	}
   260→
   261→	// 상하좌우 데미지 처리
   262→	const FVector& BrickSize = BrickProperties.Size;
   263→	const FVector CurrentLocation = GetComponentLocation();
   264→
   265→	TArray<FVector> ExplosionDirections = {
   266→		FVector(BrickSize.X, 0.0f, 0.0f),   // Right
   267→		FVector(-BrickSize.X, 0.0f, 0.0f),  // Left
   268→		FVector(0.0f, BrickSize.Y, 0.0f),   // Up
   269→		FVector(0.0f, -BrickSize.Y, 0.0f)   // Down
   270→	};
   271→
   272→	for (const FVector& Dir : ExplosionDirections)
   273→	{
   274→		FVector CheckLocation = CurrentLocation + Dir;
   275→
   276→		// 해당 위치의 캐릭터나 다른 오브젝트에 데미지
   277→		TArray<FOverlapResult> Overlaps;
   278→		FCollisionShape CollisionShape = FCollisionShape::MakeBox(BrickSize * 0.4f);
   279→
   280→		if (GetWorld()->OverlapMultiByChannel(
   281→			Overlaps,
   282→			CheckLocation,
   283→			FQuat::Identity,
   284→			ECC_Pawn,
   285→			CollisionShape))
   286→		{
   287→			for (const FOverlapResult& Overlap : Overlaps)
   288→			{
   289→				if (AWjWorldCharacterPlay* Character = Cast<AWjWorldCharacterPlay>(Overlap.GetActor()))
   290→				{
   291→					// 캐릭터에 데미지 또는 제거 처리
   292→					if (UWjWorldGameRuleApproachingWall* GameRule = Cast<UWjWorldGameRuleApproachingWall>(GetGameModePlay()->GetCurrentGameRule()))
   293→					{
   294→						GameRule->OnPlayerEliminated(Character);
   295→					}
   296→				}
   297→			}
   298→		}
   299→	}
   300→}
