   302→void UWjWorldBrickComponent::DestroyBrick()
   303→{
   304→	// 파괴 VFX
   305→	if (AWjWorldBrickActor* BrickActor = Cast<AWjWorldBrickActor>(GetOwner()))
   306→	{
   307→		BrickActor->MulticastSpawnDestroyEffect();
   308→	}
   309→
   310→	ReserveDestroyBrick(0.1f);
   311→}
   312→
   313→void UWjWorldBrickComponent::ApplyDamage(int32 DamageAmount)
   314→{
   315→	if (GetOwnerRole() != ROLE_Authority) return;
   316→	if (CurrentHP <= 0) return;
   317→
   318→	CurrentHP = FMath::Max(0, CurrentHP - DamageAmount);
   319→
   320→	if (CurrentHP <= 0)
   321→	{
   322→		// HP 소진 → 파쇄 연출 + 파괴
   323→		if (AWjWorldBrickActor* BrickActor = Cast<AWjWorldBrickActor>(GetOwner()))
   324→		{
   325→			BrickActor->MulticastSpawnDestructionFracture();
   326→		}
   327→		DestroyBrick();
   328→	}
   329→	else
   330→	{
   331→		// 서버에서도 비주얼 업데이트 (클라이언트는 OnRep에서 호출)
   332→		UpdateDamageVisuals();
   333→	}
   334→}
