   341→void UWjWorldBrickComponent::UpdateDamageVisuals()
   342→{
   343→	if (!BrickMeshComponent) return;
   344→
   345→	UMaterialInstanceDynamic* DynamicMaterial = Cast<UMaterialInstanceDynamic>(BrickMeshComponent->GetMaterial(0));
   346→	if (!DynamicMaterial) return;
   347→
   348→	const int32 MaxHP = BrickProperties.MaxHP;
   349→	if (MaxHP <= 0) return;
   350→
   351→	// HP 비율: 1.0(풀HP) → 0.0(체력 없음)
   352→	const float HPRatio = static_cast<float>(CurrentHP) / static_cast<float>(MaxHP);
   353→
   354→	// BaseColor: Black(풀HP) → DarkRed(중간) → Red(저HP)
   355→	const FLinearColor FullHPColor = FLinearColor::Black;
   356→	const FLinearColor LowHPColor = FLinearColor::Red;
   357→	const FLinearColor InterpolatedColor = FMath::Lerp(LowHPColor, FullHPColor, HPRatio);
   358→	DynamicMaterial->SetVectorParameterValue(FName("BaseColor"), InterpolatedColor);
   359→
   360→	// CrackIntensity: 0.0(풀HP) → 1.0(저HP)
   361→	const float CrackIntensity = 1.0f - HPRatio;
   362→	DynamicMaterial->SetScalarParameterValue(FName("CrackIntensity"), CrackIntensity);
   363→}
