    85→FVector UWjWorldBrickSpawner::CalculateBrickPosition(int32 BrickColIndex, int32 BrickRowIndex, int32 ColNum, int32 RowNum, const FVector& WallOrigin, const FVector& BrickSize)
    86→{
    87→	// 그리드 중심 인덱스 (정중앙 기준)
    88→	const float CenterCol = (ColNum - 1) * 0.5f;
    89→	const float CenterRow = (RowNum - 1) * 0.5f;
    90→
    91→	// 중심으로부터의 오프셋 (그리드 좌표계)
    92→	const float ColOffset = BrickColIndex - CenterCol;
    93→	const float RowOffset = BrickRowIndex - CenterRow;
    94→
    95→	// 월드 오프셋 (BrickSize 반영)
    96→	const float WorldOffsetX = ColOffset * BrickSize.X;
    97→	const float WorldOffsetY = RowOffset * BrickSize.Y;
    98→
    99→	return WallOrigin + FVector(WorldOffsetX, WorldOffsetY, BrickSize.Z / 2.0);
   100→}
