    44→void UGA_NormalAttack::ActivateAbility(const FGameplayAbilitySpecHandle Handle, const FGameplayAbilityActorInfo* ActorInfo, const FGameplayAbilityActivationInfo ActivationInfo, const FGameplayEventData* TriggerEventData)
    45→{
    46→	Super::ActivateAbility(Handle, ActorInfo, ActivationInfo, TriggerEventData);
    47→
    48→	// EndAbility 호출용 캐시
    49→	CachedHandle = Handle;
    50→	CachedActorInfo = ActorInfo;
    51→	CachedActivationInfo = ActivationInfo;
    52→
    53→	// WallDesc 캐시
    54→	UWorld* World = GetWorld();
    55→	AWjWorldGameModePlay* GameModePlay = World ? World->GetAuthGameMode<AWjWorldGameModePlay>() : nullptr;
    56→	if (GameModePlay)
    57→	{
    58→		UWjWorldGameRuleApproachingWall* GameRule = GameModePlay->GetCurrentGameRule<UWjWorldGameRuleApproachingWall>();
    59→		if (GameRule)
    60→		{
    61→			CachedWallDesc = GameRule->GetWallDesc();
    62→		}
    63→	}
    64→
    65→	// GameplayCue 실행 (사운드/VFX)
    66→	if (UAbilitySystemComponent* ASC = ActorInfo->AbilitySystemComponent.Get())
    67→	{
    68→		FGameplayCueParameters CueParams;
    69→		CueParams.Location = GetAvatarActorFromActorInfo()->GetActorLocation();
    70→		ASC->ExecuteGameplayCue(WjWorldGameplayTag::GameplayCue_Ability_NormalAttack(), CueParams);
    71→	}
    72→
    73→	// 공격 로직 즉시 실행 (Montage와 별개로)
    74→	ExecuteAttack(ActivationInfo);
    75→
    76→	// 쿨다운 적용
    77→	ApplyCooldown(Handle, ActorInfo, ActivationInfo);
    78→
    79→	// Montage가 있으면 재생, 없으면 즉시 종료
    80→	if (AttackMontage)
    81→	{
    82→		UAbilityTask_PlayMontageAndWait* MontageTask = UAbilityTask_PlayMontageAndWait::CreatePlayMontageAndWaitProxy(
    83→			this,
    84→			NAME_None,
    85→			AttackMontage,
    86→			MontagePlayRate,
    87→			NAME_None,
    88→			true,  // bStopWhenAbilityEnds
    89→			1.0f   // AnimRootMotionTranslationScale
    90→		);
    91→
    92→		MontageTask->OnCompleted.AddDynamic(this, &UGA_NormalAttack::OnMontageCompleted);
    93→		MontageTask->OnBlendOut.AddDynamic(this, &UGA_NormalAttack::OnMontageBlendOut);
    94→		MontageTask->OnInterrupted.AddDynamic(this, &UGA_NormalAttack::OnMontageInterrupted);
    95→		MontageTask->OnCancelled.AddDynamic(this, &UGA_NormalAttack::OnMontageCancelled);
    96→		MontageTask->ReadyForActivation();
    97→	}
    98→	else
    99→	{
   100→		// Montage 없으면 즉시 종료
   101→		EndAbility(Handle, ActorInfo, ActivationInfo, true, false);
   102→	}
   103→}
