   105→void UGA_NormalAttack::ExecuteAttack(const FGameplayAbilityActivationInfo& ActivationInfo)
   106→{
   107→	// 서버에서만 공격 처리
   108→	if (!HasAuthority(&ActivationInfo))
   109→	{
   110→		return;
   111→	}
   112→
   113→	FVector TargetLocation = CalculateTargetLocation();
   114→	FVector HalfSize = CachedWallDesc.BrickSize * 0.3f;
   115→
   116→	// BrickSize가 0이면 플레이어 감지용 기본 범위 사용
   117→	if (HalfSize.IsNearlyZero())
   118→	{
   119→		HalfSize = FVector(75.f, 75.f, 90.f);
   120→	}
   121→
   122→	TArray<FOverlapResult> Overlaps;
   123→	FCollisionShape CollisionShape = FCollisionShape::MakeBox(HalfSize);
   124→
   125→	if (GetWorld()->OverlapMultiByObjectType(
   126→		Overlaps,
   127→		TargetLocation,
   128→		FQuat::Identity,
   129→		FCollisionObjectQueryParams::AllObjects,
   130→		CollisionShape))
   131→	{
   132→		AActor* AvatarActor = GetAvatarActorFromActorInfo();
   133→
   134→		for (const FOverlapResult& Overlap : Overlaps)
   135→		{
   136→			// 벽돌 감지
   137→			AWjWorldBrickActor* BrickActor = Cast<AWjWorldBrickActor>(Overlap.GetActor());
   138→			if (BrickActor)
   139→			{
   140→				UWjWorldBrickComponent* BrickComp = BrickActor->GetBrickComponent();
   141→				if (!BrickComp) continue;
   142→
   143→				const FWjWorldBrickProperties& Props = BrickComp->GetBrickProperties();
   144→
   145→				switch (Props.BrickType)
